//SOUND_BEGIN
// =========================================================================
// Title: Alien Thorns
// Author: Dave Hoskins
// Source: https://www.shadertoy.com/view/XsSSzD
// License: CC BY-NC-SA 3.0 (Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported)
//
// Note: Adapted for Desktop GLSL Audio. Removed dependencies on iChannel0 
//       and iChannel3. Replaced with mathematical hash functions.
// =========================================================================
// =========================================================================
// Title: Voronoi Thorns Synth
// Note: Adattato per Desktop GLSL Audio. Rimosse le dipendenze da iChannel0 
// e iChannel3. Sostituite con funzioni di hash matematiche.
// =========================================================================

// Alien Thorns Audio - Procedural & RHI Safe Version

#define MOD3 vec3(0.0631, 0.07369, 0.08787)
float gTime;

//--------------------------------------------------------------------------------------------------
vec2 Hash2(vec2 p)
{
    vec3 p3 = fract(vec3(p.xyx) * MOD3);
    p3 += dot(p3.zxy, p3.yxz+19.19);
    return fract(vec2(p3.x * p3.y, p3.z*p3.x));
}

//--------------------------------------------------------------------------------------------------
vec2 Noise( in vec2 x )
{
    return mix(Hash2(floor(x)), Hash2(floor(x)+1.0), fract(x));
}

float Saw(float n, float fil)
{
    float v = 0.0;
    float f = 1.0;
    int filt = int(fil);

    for (int i = 0; i < 100; i++)
    {
        if (i > filt) break;
        float a = 0.5 * (sin(2.0 * f * n * PI) / f);
        if (i > filt - filt/10) a = 2.5 * a;
        v += a;
        f++;
    }
    return v * 2000.0 / (fil + 1000.0);
}

// Sostituzione procedurale della texture iChannel0
vec2 Hash( vec2 n )
{
    vec3 p3 = fract(vec3(n.xyx) * MOD3);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.xx + p3.yz) * p3.zy);
}

//--------------------------------------------------------------------------
vec2 Noise2D( in vec2 x )
{
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    vec2 res = mix(mix( Hash(p + 0.0), Hash(p + vec2(1.0, 0.0)), f.x),
                   mix( Hash(p + vec2(0.0, 1.0) ), Hash(p + vec2(1.0, 1.0)), f.x), f.y);
    return res - 0.5;
}

//--------------------------------------------------------------------------
vec2 FBM( vec2 p )
{
    vec2 f;
    f  = 0.5000  * Noise2D(p); p = p * 2.32;
    f += 0.2500  * Noise2D(p); p = p * 2.23;
    f += 0.1250  * Noise2D(p); p = p * 2.31;
    f += 0.0625  * Noise2D(p); p = p * 2.28;
    f += 0.03125 * Noise2D(p);
    return f;
}

//--------------------------------------------------------------------------------------------------
vec4 ThornVoronoi( vec3 p)
{
    vec2 f = fract(p.xz);
    p.xz = floor(p.xz);
    float d = 1.0e10;
    vec3 id = vec3(0.0);

    for (int xo = -1; xo <= 1; xo++)
    {
        for (int yo = -1; yo <= 1; yo++)
        {
            // FIX CRITICO RHI: Cast esplicito da int a float
            vec2 g = vec2(float(xo), float(yo));

            // Sostituzione procedurale della texture iChannel3
            vec3 p3 = fract(vec3((p.xz + g + 0.5).xyx) * MOD3);
            p3 += dot(p3, p3.yzx + 19.19);
            vec2 n = fract((p3.xx + p3.yz) * p3.zy);

            n = n * n * (3.0 - 2.0 * n);

            vec2 tp = g + 0.5 + sin(p.y + 1.2831 * (n * gTime * 0.5)) - f;
            float d2 = dot(tp, tp);
            if (d2 < d)
            {
                d = d2;
                id = vec3(tp.x, p.y, tp.y);
            }
        }
    }

    return vec4(id, 1.35 - pow(d, 0.17));
}

//--------------------------------------------------------------------------------------------------
float MapThorns( in vec3 pos )
{
    return pos.y * 0.21 - ThornVoronoi(pos).w  - max(pos.y - 5.0, 0.0) * 0.5 + max(pos.y - 5.5, 0.0) * 0.8;
}

//--------------------------------------------------------------------------------------------------
vec3 Path( float time_in )
{
    return vec3(1.3 + 17.2 * cos(0.2 - 0.5 * 0.33 * time_in * 0.75), 4.7, 7.6 - 16.2 * sin(0.5 * 0.11 * time_in * 0.75) );
}

//--------------------------------------------------------------------------------------------------
// Funzione d'ingresso richiesta dal sintetizzatore di Qt RHI
vec2 mainSound( in int samp, float time_in)
{
    gTime = time_in + 173.0;

    vec3 ro = Path(gTime + 0.0);
    vec3 ta = Path(gTime + 5.2);
    float add = (sin(gTime * 0.3) + 1.0) * 2.0;
    ro.y += add;
    ta.y -= add;

    vec3 cw = normalize(ta - ro);   // Linea di direzione in avanti
    vec3 cp = vec3(0.0, 1.0, 0.0);  // Vettore Up
    vec3 cu = cross(cw, cp);        // Prodotto vettoriale per direzione "orecchio destro"

    vec2 ears;
    ears.x = abs(MapThorns(ro + cu * 0.1)) * 0.8; // Orecchio Sinistro
    ears.y = abs(MapThorns(ro - cu * 0.1)) * 0.8; // Orecchio Destro

    vec2 gain = vec2(0.0);
    gain = clamp(1.0 - ears, 0.0, 1.0);
    gain = pow(gain, vec2(3.9));

    float fil1 = sin(gTime * 0.521) * 50.0 + 60.0;
    float fil2 = -sin(gTime * 0.474) * 50.0 + 60.0;

    vec2 audio;
    audio.x = gain.x * (Saw(11.125 * time_in, fil1) + Saw(22.2 * time_in, fil1));
    audio.y = gain.y * (Saw(11.125 * time_in, fil2) + Saw(22.3 * time_in, fil2));

    vec2 pos = vec2(gTime * 192.017331, gTime * 182.066927);
    pos -= sin(gTime * 0.143) * 20.0 * (gain.x + gain.y);
    audio += FBM(pos) * Saw(gTime * 10.5 - sin(gTime * 0.2) * 8.0, 30.0);

    // Dissolvenza in entrata (se necessaria) e clamping di sicurezza
    return clamp(audio, -1.0, 1.0) * smoothstep(0.0, 2.0, time_in);
}
//SOUND_END
// --- TEXTURE SCRIPT: OLOGRAFIA REATTIVA ---
// Usa questo script nel dock Texture per un oggetto implicito

// 1. Usiamo lo slider 'A' per controllare la densità della griglia (es. range 0-5)
float gridDensity = 25.0;   // how many grid cells 

// 2. Creiamo una griglia basata sulle coordinate UV della superficie
// fract() crea il pattern ripetuto, sottraiamo 0.5 per centrare la cella
vec2 grid = fract(uv * gridDensity) - 0.5; 

// 3. Calcoliamo la distanza dai bordi per disegnare le linee
float lineDist = min(abs(grid.x), abs(grid.y));

// 4. Animiamo lo spessore della linea con il tempo 't'
// Lo slider 'B' può controllare la velocità della pulsazione
float pulse = sin(t * 7.0);   // pulse speed
float thickness = 0.05 + 0.03 * pulse;

// 5. Creiamo un effetto "Glow" (bagliore) morbido ai bordi della linea
float glow = smoothstep(thickness + 0.05, thickness, lineDist);

// 6. Assegnazione dei colori usando le variabili iniettate dal tuo engine
// Il fondo usa il colore secondario (u_col2), le linee il primario (u_col1) "sparato"
vec3 baseColor = u_col2;                  // Spazio vuoto della griglia (Colore 2)
vec3 neonColor = u_col1 * 1.5;           // Il colore UI, reso più luminoso

// 7. Mixiamo i colori in base al calcolo del glow
vec3 finalColor = mix(baseColor, neonColor, glow);

return finalColor;
